export const chapters=[
 {id:1,title:'An Introduction to the Human Body',short:'The human body',description:'Find your bearings. Connect structures, systems and the language of anatomy.',color:'#d4fa80',coverage:'Atlas + essentials',sections:[['1.1','Overview of Anatomy and Physiology','foundations'],['1.2','Structural Organization of the Human Body','organs'],['1.3','Functions of Human Life','foundations'],['1.4','Requirements for Human Life','foundations'],['1.5','Homeostasis','foundations'],['1.6','Anatomical Terminology','directions']]},
 {id:2,title:'The Chemical Level of Organization',short:'The chemical level',description:'Build the chemical foundations of life, from atoms and bonds to biological molecules.',color:'#ffca95',coverage:'Essentials · partial coverage',sections:[['2.1','Elements and Atoms: The Building Blocks of Matter','chemistry'],['2.2','Chemical Bonds','chemistry'],['2.3','Chemical Reactions','chemistry'],['2.4','Inorganic Compounds Essential to Human Functioning','chemistry'],['2.5','Organic Compounds Essential to Human Functioning','chemistry']]},
 {id:3,title:'The Cellular Level of Organization',short:'The cellular level',description:'Step inside the cell. Explore membranes, decode DNA and bring cellular processes to life.',color:'#75eee2',coverage:'Lessons · diagrams · labs',sections:[['3.1','The Cell Membrane','membrane'],['3.2','The Cytoplasm and Cellular Organelles','organelles'],['3.3','The Nucleus and DNA Replication','nucleus'],['3.4','Protein Synthesis','protein'],['3.5','Cell Growth and Division','division'],['3.6','Cellular Differentiation','differentiation']]}
];
chapters.push({id:4,title:'The Tissue Level of Organization',short:'The tissue level',description:'Read the architecture of life. Explore tissues, compare microscopic evidence and trace repair.',color:'#c8a4ff',coverage:'Lessons · tissue diagrams · practice',sections:[['4.1','Types of Tissues','types'],['4.2','Epithelial Tissue','epithelial'],['4.3','Connective Tissue Supports and Protects','connective'],['4.4','Muscle Tissue and Motion','muscle'],['4.5','Nervous Tissue Mediates Perception and Response','nervous'],['4.6','Tissue Injury and Aging','repair']]});
for(const c of chapters){c.studio=c.id>=3?`chapter${c.id}/`:null;c.progressKey=c.id===3?'soma-cell-studio-v1':c.id===4?'soma-tissue-studio-v1':'soma-inside-v1';}
export const slug=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/-$/,'');
export const textbook=(section)=>'https://openstax.org/books/anatomy-and-physiology-2e/pages/'+section[0].replace('.','-')+'-'+slug(section[1]);
export const sectionLink=(c,s)=>c.studio?`${c.studio}#module/${s[2]}/learn`:`atlas.html#chapter/${c.id}/section/${s[0]}/${s[2]}/study`;
export const read=(key,fallback={})=>{try{return JSON.parse(localStorage.getItem(key))||fallback;}catch{return fallback;}};
export const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
